'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { createMemoryStore } = require('../src/exports/store');
const { purgeExpiredExports, MS_PER_DAY } = require('../src/exports/purge');

const NOW = new Date('2026-10-08T00:00:00Z');
const daysAgo = (n) => new Date(NOW.getTime() - n * MS_PER_DAY);

test('deletes exports older than the retention period', () => {
  const store = createMemoryStore([
    { name: 'old.csv', createdAt: daysAgo(31) },
    { name: 'fresh.csv', createdAt: daysAgo(5) },
  ]);

  const result = purgeExpiredExports({ store, now: NOW, retentionDays: 30 });

  assert.deepEqual(result.deleted, ['old.csv']);
  assert.deepEqual(result.retained, ['fresh.csv']);
  assert.deepEqual(
    store.list().map((e) => e.name),
    ['fresh.csv']
  );
});

test('keeps an export exactly at the cutoff', () => {
  const store = createMemoryStore([{ name: 'edge.csv', createdAt: daysAgo(30) }]);

  const result = purgeExpiredExports({ store, now: NOW, retentionDays: 30 });

  assert.deepEqual(result.deleted, []);
  assert.deepEqual(result.retained, ['edge.csv']);
  assert.equal(store.list().length, 1);
});

test('retention period changes which exports expire', () => {
  const entries = [{ name: 'mid.csv', createdAt: daysAgo(60) }];

  const at30 = createMemoryStore(entries);
  assert.deepEqual(purgeExpiredExports({ store: at30, now: NOW, retentionDays: 30 }).deleted, [
    'mid.csv',
  ]);

  const at90 = createMemoryStore(entries);
  assert.deepEqual(purgeExpiredExports({ store: at90, now: NOW, retentionDays: 90 }).deleted, []);
});

test('never deletes exports flagged as exempt (legal hold)', () => {
  const store = createMemoryStore([
    { name: 'held.csv', createdAt: daysAgo(400), legalHold: true },
    { name: 'plain.csv', createdAt: daysAgo(400) },
  ]);

  const result = purgeExpiredExports({
    store,
    now: NOW,
    retentionDays: 30,
    isExempt: (e) => e.legalHold === true,
  });

  assert.deepEqual(result.exempt, ['held.csv']);
  assert.deepEqual(result.deleted, ['plain.csv']);
  assert.deepEqual(
    store.list().map((e) => e.name),
    ['held.csv']
  );
});

test('dryRun reports what would be deleted without removing anything', () => {
  const store = createMemoryStore([{ name: 'old.csv', createdAt: daysAgo(31) }]);

  const result = purgeExpiredExports({ store, now: NOW, retentionDays: 30, dryRun: true });

  assert.deepEqual(result.deleted, ['old.csv']);
  assert.equal(result.dryRun, true);
  assert.equal(store.list().length, 1, 'dry run must not delete');
});

test('refuses to delete while the retention period is unconfigured', () => {
  const store = createMemoryStore([{ name: 'old.csv', createdAt: daysAgo(999) }]);

  // config/retention.js has exportRetentionDays: null pending compliance.
  assert.throws(() => purgeExpiredExports({ store, now: NOW }), /not configured/);
  assert.equal(store.list().length, 1, 'nothing deleted when period is unknown');
});

test('rejects an invalid retention period', () => {
  const store = createMemoryStore([]);
  assert.throws(() => purgeExpiredExports({ store, now: NOW, retentionDays: -1 }), TypeError);
  assert.throws(() => purgeExpiredExports({ store, now: NOW, retentionDays: '30' }), TypeError);
});

test('rejects a missing store or invalid now', () => {
  assert.throws(() => purgeExpiredExports({ now: NOW, retentionDays: 30 }), TypeError);
  assert.throws(
    () => purgeExpiredExports({ store: createMemoryStore([]), now: 'today', retentionDays: 30 }),
    TypeError
  );
});

test('refuses to delete an entry with an unreadable createdAt', () => {
  const store = createMemoryStore([{ name: 'bad.csv', createdAt: new Date('nope') }]);

  assert.throws(
    () => purgeExpiredExports({ store, now: NOW, retentionDays: 30 }),
    /invalid createdAt/
  );
  assert.equal(store.list().length, 1);
});

test('empty store is a no-op', () => {
  const result = purgeExpiredExports({ store: createMemoryStore([]), now: NOW, retentionDays: 30 });
  assert.deepEqual(result.deleted, []);
  assert.deepEqual(result.retained, []);
});
